use std::io

fn find(keys: Vec<int>, k: int) -> int {
    let mut i = 0
    while i < keys.len() {
        if keys[i] == k {
            return i
        }
        i += 1
    }
    return -1
}

fn main() {
    let first = io::read_line().unwrap_or("")
    let cap = first.trim().parse::<int>().unwrap_or(1)
    let mut keys: Vec<int> = Vec::new()
    let mut vals: Vec<int> = Vec::new()
    loop {
        let raw = io::read_line().unwrap_or("")
        let line = raw.trim()
        if line.len() == 0 {
            break
        }
        let parts: Vec<string> = line.split_whitespace().collect()
        let cmd = parts[0]
        if cmd == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let idx = find(keys.clone(), k)
            if idx >= 0 {
                keys.remove(idx)
                vals.remove(idx)
            }
            keys.push(k)
            vals.push(v)
            if keys.len() > cap {
                let ev = keys[0]
                keys.remove(0)
                vals.remove(0)
                println("evict ${ev}")
            }
        } else if cmd == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let idx = find(keys.clone(), k)
            if idx < 0 {
                println("-1")
            } else {
                let v = vals[idx]
                keys.remove(idx)
                vals.remove(idx)
                keys.push(k)
                vals.push(v)
                println("${v}")
            }
        } else if cmd == "keys" {
            if keys.len() == 0 {
                println("<empty>")
            } else {
                let mut out = ""
                let mut i = keys.len()
                while i > 0 {
                    i -= 1
                    if out.len() > 0 {
                        out = out + " "
                    }
                    out = out + keys[i].to_string()
                }
                println("${out}")
            }
        }
    }
}

